{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/kairos-community/isotope/test/agent/fixture.schema.json",
  "title": "Isotope Cua agent VM fixture descriptor",
  "description": "Frozen contract emitted by test/agent/run.sh fixture (Phase 4, Task 3) and consumed by the Go smoke client (Task 4) and downstream CI gates. Exactly these eight string fields, nothing else.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "mcp_url",
    "bearer_token_file",
    "ca_certificate_file",
    "tls_fingerprint",
    "vnc_address",
    "novnc_url",
    "qmp_socket",
    "artifact_directory"
  ],
  "properties": {
    "mcp_url": {
      "type": "string",
      "format": "uri",
      "pattern": "^https://.+/mcp$",
      "description": "HTTPS URL of the gateway MCP endpoint, e.g. https://127.0.0.1:7443/mcp. Must be https and must end in /mcp."
    },
    "bearer_token_file": {
      "type": "string",
      "pattern": "^/.+",
      "description": "Absolute path to a mode-0600 file containing the plaintext bearer token (hdn_u_... or hdn_a_...). Never embed the token value itself in the descriptor."
    },
    "ca_certificate_file": {
      "type": "string",
      "pattern": "^/.+",
      "description": "Absolute path to the PEM-encoded self-signed leaf certificate captured via TOFU, for pinned TLS verification."
    },
    "tls_fingerprint": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$",
      "description": "Lowercase hex SHA-256 digest of the DER-encoded leaf certificate (64 characters)."
    },
    "vnc_address": {
      "type": "string",
      "minLength": 1,
      "description": "Loopback VNC listen address in host:port form, e.g. 127.0.0.1:5910."
    },
    "novnc_url": {
      "type": "string",
      "description": "HTTP URL of the noVNC web console, or the empty string when noVNC is disabled for this fixture."
    },
    "qmp_socket": {
      "type": "string",
      "pattern": "^/.+",
      "description": "Absolute path to the QMP control-socket Unix domain socket."
    },
    "artifact_directory": {
      "type": "string",
      "pattern": "^/.+",
      "description": "Absolute path to the directory where this fixture instance writes logs, screenshots, and results."
    }
  }
}

package api_test

import (
	"strings"
	"testing"

	"github.com/kairos-community/isotope/agent/internal/api"
)

func intPtr(v int) *int { return &v }

// TestBrowserInputValidate covers the per-action field matrix: an action must
// carry what it needs and must not carry fields belonging to another action.
// The second half matters as much as the first -- silently ignoring a field a
// caller set is how a click on the wrong thing gets reported as a success.
func TestBrowserInputValidate(t *testing.T) {
	cases := []struct {
		name    string
		in      api.BrowserInput
		wantErr string // substring; empty means the input must validate
	}{
		{
			name: "navigate with url",
			in:   api.BrowserInput{Action: api.BrowserNavigate, URL: "https://kairos.io"},
		},
		{
			name:    "navigate without url",
			in:      api.BrowserInput{Action: api.BrowserNavigate},
			wantErr: "requires url",
		},
		{
			name:    "navigate rejects a ref",
			in:      api.BrowserInput{Action: api.BrowserNavigate, URL: "https://kairos.io", Ref: "e1"},
			wantErr: "does not accept field(s): [ref]",
		},
		{
			name: "snapshot needs nothing",
			in:   api.BrowserInput{Action: api.BrowserSnapshot},
		},
		{
			name: "snapshot bounds elements",
			in:   api.BrowserInput{Action: api.BrowserSnapshot, MaxElements: intPtr(50)},
		},
		{
			name:    "snapshot rejects text",
			in:      api.BrowserInput{Action: api.BrowserSnapshot, Text: "hello"},
			wantErr: "does not accept field(s): [text]",
		},
		{
			name: "click with ref",
			in:   api.BrowserInput{Action: api.BrowserClick, Ref: "e7"},
		},
		{
			name:    "click without ref",
			in:      api.BrowserInput{Action: api.BrowserClick},
			wantErr: "requires ref",
		},
		{
			name: "type with ref and text",
			in:   api.BrowserInput{Action: api.BrowserType, Ref: "e2", Text: "kairos"},
		},
		{
			name: "type may submit",
			in:   api.BrowserInput{Action: api.BrowserType, Ref: "e2", Text: "kairos", Submit: true},
		},
		{
			name:    "type without text",
			in:      api.BrowserInput{Action: api.BrowserType, Ref: "e2"},
			wantErr: "requires text",
		},
		{
			name: "press with key",
			in:   api.BrowserInput{Action: api.BrowserPress, Key: "Enter"},
		},
		{
			name:    "press without key",
			in:      api.BrowserInput{Action: api.BrowserPress},
			wantErr: "requires key",
		},
		{
			name: "scroll with direction",
			in:   api.BrowserInput{Action: api.BrowserScroll, Direction: api.DirectionDown},
		},
		{
			name:    "scroll without direction",
			in:      api.BrowserInput{Action: api.BrowserScroll},
			wantErr: "requires direction",
		},
		{
			name:    "scroll rejects an unknown direction",
			in:      api.BrowserInput{Action: api.BrowserScroll, Direction: "sideways"},
			wantErr: `invalid direction "sideways"`,
		},
		{
			name: "back needs nothing",
			in:   api.BrowserInput{Action: api.BrowserBack},
		},
		{
			name: "text without a ref reads the document",
			in:   api.BrowserInput{Action: api.BrowserText},
		},
		{
			name: "text with a ref reads the element",
			in:   api.BrowserInput{Action: api.BrowserText, Ref: "e3"},
		},
		{
			name: "window_id is accepted by every action",
			in:   api.BrowserInput{Action: api.BrowserBack, WindowID: intPtr(4194304)},
		},
		{
			name:    "unknown action",
			in:      api.BrowserInput{Action: "teleport"},
			wantErr: `unknown action "teleport"`,
		},
		{
			name:    "empty action",
			in:      api.BrowserInput{},
			wantErr: `unknown action ""`,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := tc.in.Validate()
			switch {
			case tc.wantErr == "" && err != nil:
				t.Fatalf("Validate() = %v, want nil", err)
			case tc.wantErr != "" && err == nil:
				t.Fatalf("Validate() = nil, want error containing %q", tc.wantErr)
			case tc.wantErr != "" && !strings.Contains(err.Error(), tc.wantErr):
				t.Fatalf("Validate() = %q, want it to contain %q", err, tc.wantErr)
			}
		})
	}
}

// TestBrowserSubmitFalseIsNotAField guards the one field whose "was it set?"
// answer is not obvious: Submit is a bool, so an explicit false is
// indistinguishable from unset. It must not count as present, or every action
// that does not allow it would reject a caller who sent submit:false.
func TestBrowserSubmitFalseIsNotAField(t *testing.T) {
	in := api.BrowserInput{Action: api.BrowserBack, Submit: false}
	if err := in.Validate(); err != nil {
		t.Fatalf("submit:false on back = %v, want nil", err)
	}
	if err := (api.BrowserInput{Action: api.BrowserBack, Submit: true}).Validate(); err == nil {
		t.Fatal("submit:true on back = nil, want a rejection")
	}
}

package gateway

import (
	"context"
	"crypto/tls"
	"io"
	"net"
	"net/http"
	"strings"
	"testing"
	"time"

	"github.com/kairos-community/isotope/agent/internal/control"
)

// ---------------------------------------------------------------------------
// Listen-address validation and --insecure-loopback
// ---------------------------------------------------------------------------

func TestValidateListen(t *testing.T) {
	cases := []struct {
		addr             string
		insecureLoopback bool
		wantErr          bool
	}{
		{"0.0.0.0:7443", false, false},
		{"127.0.0.1:7443", true, false},
		{"localhost:7443", true, false},
		{"[::1]:7443", true, false},
		{"0.0.0.0:7443", true, true}, // insecure-loopback on wildcard: rejected
		{":7443", true, true},        // insecure-loopback on empty host: rejected
		{"192.168.1.5:7443", true, true},
		{"not-an-addr", false, true},
	}
	for _, tc := range cases {
		err := validateListen(tc.addr, tc.insecureLoopback)
		if (err != nil) != tc.wantErr {
			t.Errorf("validateListen(%q, %v) err=%v, wantErr=%v", tc.addr, tc.insecureLoopback, err, tc.wantErr)
		}
	}
}

func TestNewRequiresTLSUnlessInsecureLoopback(t *testing.T) {
	creds := newTestCreds(t)
	base := func() Config {
		return Config{
			ListenAddr: "0.0.0.0:7443",
			Session:    startBroker(t, &fakeBroker{healthy: true}, false),
			Verifier:   creds.verifier,
			Controller: newTestController(),
		}
	}

	// No TLS, no insecure-loopback: rejected.
	if _, err := New(base()); err == nil {
		t.Fatal("expected error when TLS absent and not insecure-loopback")
	}

	// Insecure-loopback on a non-loopback address: rejected.
	cfg := base()
	cfg.InsecureLoopback = true
	if _, err := New(cfg); err == nil {
		t.Fatal("expected error for insecure-loopback on non-loopback address")
	}

	// Insecure-loopback on loopback: accepted.
	cfg = base()
	cfg.ListenAddr = "127.0.0.1:0"
	cfg.InsecureLoopback = true
	if _, err := New(cfg); err != nil {
		t.Fatalf("insecure-loopback on loopback rejected: %v", err)
	}
}

// ---------------------------------------------------------------------------
// TLS 1.3 minimum
// ---------------------------------------------------------------------------

func TestServeEnforcesTLS13(t *testing.T) {
	creds := newTestCreds(t)
	serverTLS, pool := selfSignedTLS(t)
	g, err := New(Config{
		Version:    "v-test",
		ListenAddr: "127.0.0.1:0",
		TLSConfig:  serverTLS,
		Session:    startBroker(t, &fakeBroker{healthy: true}, false),
		Verifier:   creds.verifier,
		Controller: newTestController(),
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	go func() { _ = g.Serve(l) }()
	t.Cleanup(func() { _ = l.Close() })
	addr := l.Addr().String()

	waitDialable(t, addr)

	// A TLS 1.3 client succeeds against /healthz.
	ok := &http.Client{Transport: &http.Transport{TLSClientConfig: &tls.Config{RootCAs: pool, MinVersion: tls.VersionTLS13}}}
	resp, err := ok.Get("https://" + addr + "/healthz")
	if err != nil {
		t.Fatalf("TLS1.3 client failed: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("healthz over TLS = %d, want 200", resp.StatusCode)
	}

	// A client capped at TLS 1.2 must be refused (server MinVersion is 1.3).
	bad := &http.Client{Transport: &http.Transport{TLSClientConfig: &tls.Config{RootCAs: pool, MaxVersion: tls.VersionTLS12}}}
	if _, err := bad.Get("https://" + addr + "/healthz"); err == nil {
		t.Fatal("TLS1.2 client was not refused by a TLS1.3-minimum server")
	}
}

// ---------------------------------------------------------------------------
// Loopback-only development HTTP
// ---------------------------------------------------------------------------

func TestInsecureLoopbackServesPlainHTTP(t *testing.T) {
	creds := newTestCreds(t)
	g, err := New(Config{
		Version:          "v-test",
		ListenAddr:       "127.0.0.1:0",
		InsecureLoopback: true,
		Session:          startBroker(t, &fakeBroker{healthy: true}, false),
		Verifier:         creds.verifier,
		Controller:       newTestController(),
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	go func() { _ = g.Serve(l) }()
	t.Cleanup(func() { _ = l.Close() })
	addr := l.Addr().String()
	waitDialable(t, addr)

	resp, err := http.Get("http://" + addr + "/healthz")
	if err != nil {
		t.Fatalf("plain HTTP get: %v", err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("plain HTTP healthz = %d, want 200", resp.StatusCode)
	}
}

// ---------------------------------------------------------------------------
// Body limit (2 MiB)
// ---------------------------------------------------------------------------

func TestBodyLimitRejectsOversized(t *testing.T) {
	f := newFixture(t, func(cfg *Config, _ *fixture) {
		cfg.MaxBodyBytes = 1 << 20 // 1 MiB for a faster test
	})
	l, addr := serveInsecure(t, f.g)
	_ = l

	big := strings.Repeat("A", (1<<20)+4096)
	req, _ := http.NewRequest(http.MethodPost, "http://"+addr+"/mcp", strings.NewReader(big))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+f.creds.userBearer)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("do: %v", err)
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, resp.Body)
	if resp.StatusCode == http.StatusOK {
		t.Fatalf("oversized body accepted with 200")
	}
}

// ---------------------------------------------------------------------------
// Connection limit (limitListener)
// ---------------------------------------------------------------------------

func TestLimitListenerBoundsConnections(t *testing.T) {
	base, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	defer base.Close()
	const max = 2
	ll := newLimitListener(base, max)

	accepted := make(chan net.Conn, 8)
	go func() {
		for {
			c, err := ll.Accept()
			if err != nil {
				return
			}
			accepted <- c
		}
	}()

	addr := base.Addr().String()
	// Open `max` connections; the limiter accepts (and returns a server-side
	// conn for) each. Hold onto the server conns: a slot is freed only when a
	// server-side conn is Closed, not when the client disconnects.
	var clientConns, serverConns []net.Conn
	for range max {
		c, err := net.Dial("tcp", addr)
		if err != nil {
			t.Fatalf("dial: %v", err)
		}
		clientConns = append(clientConns, c)
		select {
		case sc := <-accepted:
			serverConns = append(serverConns, sc)
		case <-time.After(time.Second):
			t.Fatal("expected connection to be accepted")
		}
	}

	// A further connection must NOT be accepted until a slot frees.
	extra, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatalf("dial extra: %v", err)
	}
	clientConns = append(clientConns, extra)
	select {
	case <-accepted:
		t.Fatal("connection accepted beyond the limit")
	case <-time.After(300 * time.Millisecond):
		// expected: blocked at the limit.
	}

	// Close one server-side conn; that frees a slot and the extra is accepted.
	serverConns[0].Close()
	select {
	case sc := <-accepted:
		sc.Close()
	case <-time.After(2 * time.Second):
		t.Fatal("connection not accepted after a slot freed")
	}
	for _, c := range serverConns[1:] {
		c.Close()
	}
	for _, c := range clientConns {
		c.Close()
	}
}

// ---------------------------------------------------------------------------
// test helpers
// ---------------------------------------------------------------------------

func newTestController() *control.Controller {
	return control.New(control.Config{
		Version:        "v-test",
		SessionHealthy: func(context.Context) bool { return true },
		CuaHealthy:     func(context.Context) bool { return true },
	})
}

func waitDialable(t *testing.T, addr string) {
	t.Helper()
	for range 100 {
		c, err := net.DialTimeout("tcp", addr, 200*time.Millisecond)
		if err == nil {
			c.Close()
			return
		}
		time.Sleep(20 * time.Millisecond)
	}
	t.Fatalf("server at %s never became dialable", addr)
}

func serveInsecure(t *testing.T, g *Gateway) (net.Listener, string) {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	go func() { _ = g.Serve(l) }()
	t.Cleanup(func() { _ = l.Close() })
	addr := l.Addr().String()
	waitDialable(t, addr)
	return l, addr
}

package api

import (
	"fmt"
	"sort"
)

// ---------------------------------------------------------------------------
// browser
// ---------------------------------------------------------------------------

// BrowserAction selects the operation the browser tool performs.
//
// The browser tool exists because the desktop accessibility path does not
// cover web content: flatpak Chromium publishes no AT-SPI DOM tree, so a
// window-scoped computer_use accessibility query returns a single node and
// there is nothing to locate a link by name with. That leaves screen
// coordinates, which encode window geometry, viewport width, responsive
// breakpoints, scroll offset, and banner state -- and which fail by clicking
// something else rather than by erroring.
//
// Every targeting action here takes a Ref from a Snapshot of the page's own
// accessibility information instead. See
// docs/superpowers/specs/2026-07-20-browser-tool-amendment.md.
type BrowserAction string

const (
	BrowserNavigate BrowserAction = "navigate"
	BrowserSnapshot BrowserAction = "snapshot"
	BrowserClick    BrowserAction = "click"
	BrowserType     BrowserAction = "type"
	BrowserPress    BrowserAction = "press"
	BrowserScroll   BrowserAction = "scroll"
	BrowserBack     BrowserAction = "back"
	BrowserText     BrowserAction = "text"
)

// BrowserActions is the closed, ordered set of browser actions.
var BrowserActions = []BrowserAction{
	BrowserNavigate,
	BrowserSnapshot,
	BrowserClick,
	BrowserType,
	BrowserPress,
	BrowserScroll,
	BrowserBack,
	BrowserText,
}

var validBrowserActions = validSet(BrowserActions)

// BrowserElement is one interactive element from a snapshot. Ref is the handle
// every targeting action uses; it is valid until the page navigates or the next
// snapshot replaces it, after which acting on it is an error rather than a
// click on whatever now occupies that position.
type BrowserElement struct {
	Ref  string `json:"ref"`
	Role string `json:"role"`
	Name string `json:"name,omitempty"`
	// Value is the current value of a form control, when it has one.
	Value string `json:"value,omitempty"`
	// X and Y are viewport-relative CSS pixels, as the page itself sees them.
	X      int `json:"x"`
	Y      int `json:"y"`
	Width  int `json:"width"`
	Height int `json:"height"`

	// ScreenX and ScreenY are the same point in SCREEN coordinates, which is
	// what computer_use clicks in. The two differ by the browser's chrome --
	// tab strip, URL bar, any notification banner -- plus the window's own
	// position, and the gap is large: 156px on a stock window. Handing a
	// caller only viewport bounds and inviting them to "fall back to
	// computer_use" produced a click 158px above its target.
	//
	// They are omitted when the window geometry could not be read, so a
	// caller can tell "no conversion available" from "the origin is 0,0".
	ScreenX *int `json:"screen_x,omitempty"`
	ScreenY *int `json:"screen_y,omitempty"`
}

// BrowserInput is the single input type for the browser tool. Only the fields
// relevant to Action are meaningful; Validate rejects requests that set fields
// irrelevant to Action, or omit fields Action requires.
type BrowserInput struct {
	Action BrowserAction `json:"action" jsonschema:"the browser operation to perform"`

	// URL is the address navigate loads.
	URL string `json:"url,omitempty" jsonschema:"absolute URL for navigate"`

	// Ref identifies a snapshot element for click, type, text, and scroll.
	Ref string `json:"ref,omitempty" jsonschema:"element ref from a snapshot"`

	// Text is typed into the element Ref names.
	Text string `json:"text,omitempty" jsonschema:"text to type into the referenced element"`

	// Submit asks type to submit the element's form afterwards. It counts as
	// set only when true, so an explicit false is never treated as a field
	// belonging to some other action.
	Submit bool `json:"submit,omitempty" jsonschema:"submit the form after typing"`

	// Key is the key press delivers to the focused element, for example
	// "Enter", "Escape", or "Tab".
	Key string `json:"key,omitempty" jsonschema:"key name for press, e.g. Enter"`

	// Direction and Amount configure scroll. Amount is in CSS pixels.
	Direction ScrollDirection `json:"direction,omitempty" jsonschema:"scroll direction: up, down, left, or right"`
	Amount    *int            `json:"amount,omitempty" jsonschema:"scroll distance in CSS pixels"`

	// MaxElements bounds how many elements a snapshot returns.
	MaxElements *int `json:"max_elements,omitempty" jsonschema:"maximum number of elements to return from a snapshot"`

	// WindowID selects which browser window to act on. It is optional: with a
	// single browser open the tool resolves the window itself, so a caller
	// never has to know a pid. With more than one open, omitting it is an
	// error rather than a silent pick.
	WindowID *int `json:"window_id,omitempty" jsonschema:"browser window to target when more than one is open"`
}

// bField identifies one optional BrowserInput field for per-action
// allow-listing.
type bField uint32

const (
	bURL bField = 1 << iota
	bRef
	bText
	bSubmit
	bKey
	bDirection
	bAmount
	bMaxElements
	bWindowID
)

var bFieldNames = map[bField]string{
	bURL:         "url",
	bRef:         "ref",
	bText:        "text",
	bSubmit:      "submit",
	bKey:         "key",
	bDirection:   "direction",
	bAmount:      "amount",
	bMaxElements: "max_elements",
	bWindowID:    "window_id",
}

// presentFields returns the bitmask of optional fields that are set on in.
func (in BrowserInput) presentFields() bField {
	var f bField
	if in.URL != "" {
		f |= bURL
	}
	if in.Ref != "" {
		f |= bRef
	}
	if in.Text != "" {
		f |= bText
	}
	if in.Submit {
		f |= bSubmit
	}
	if in.Key != "" {
		f |= bKey
	}
	if in.Direction != "" {
		f |= bDirection
	}
	if in.Amount != nil {
		f |= bAmount
	}
	if in.MaxElements != nil {
		f |= bMaxElements
	}
	if in.WindowID != nil {
		f |= bWindowID
	}
	return f
}

// rejectExtraneous returns an error naming the first field set on in that is
// not present in allowed.
func (in BrowserInput) rejectExtraneous(allowed bField) error {
	extra := in.presentFields() &^ allowed
	if extra == 0 {
		return nil
	}
	var names []string
	for bit, name := range bFieldNames {
		if extra&bit != 0 {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return fmt.Errorf("action %q does not accept field(s): %v", in.Action, names)
}

// Validate checks that BrowserInput carries a recognized Action, that every
// field set is relevant to that Action, and that Action's required fields are
// present.
func (in BrowserInput) Validate() error {
	if !validBrowserActions[in.Action] {
		return fmt.Errorf("unknown action %q", in.Action)
	}

	switch in.Direction {
	case "", DirectionUp, DirectionDown, DirectionLeft, DirectionRight:
	default:
		return fmt.Errorf("invalid direction %q", in.Direction)
	}

	switch in.Action {
	case BrowserNavigate:
		if err := in.rejectExtraneous(bURL | bWindowID); err != nil {
			return err
		}
		if in.URL == "" {
			return fmt.Errorf("action %q requires url", in.Action)
		}

	case BrowserSnapshot:
		if err := in.rejectExtraneous(bMaxElements | bWindowID); err != nil {
			return err
		}

	case BrowserClick:
		if err := in.rejectExtraneous(bRef | bWindowID); err != nil {
			return err
		}
		if in.Ref == "" {
			return fmt.Errorf("action %q requires ref", in.Action)
		}

	case BrowserType:
		if err := in.rejectExtraneous(bRef | bText | bSubmit | bWindowID); err != nil {
			return err
		}
		if in.Ref == "" {
			return fmt.Errorf("action %q requires ref", in.Action)
		}
		if in.Text == "" {
			return fmt.Errorf("action %q requires text", in.Action)
		}

	case BrowserPress:
		if err := in.rejectExtraneous(bKey | bWindowID); err != nil {
			return err
		}
		if in.Key == "" {
			return fmt.Errorf("action %q requires key", in.Action)
		}

	case BrowserScroll:
		// ref is optional: without one the page scrolls, with one that element
		// does. Real pages put content in scrollable regions -- a chat pane, a
		// table, a sidebar -- that window scrolling never touches.
		if err := in.rejectExtraneous(bRef | bDirection | bAmount | bWindowID); err != nil {
			return err
		}
		if in.Direction == "" {
			return fmt.Errorf("action %q requires direction", in.Action)
		}

	case BrowserBack:
		if err := in.rejectExtraneous(bWindowID); err != nil {
			return err
		}

	case BrowserText:
		// ref is optional: without one, the whole document's text is returned.
		if err := in.rejectExtraneous(bRef | bWindowID); err != nil {
			return err
		}
	}
	return nil
}

// BrowserOutput is the result of a browser call. Which fields are populated
// depends on the action: navigate/click/back report where the page ended up,
// snapshot returns elements, text returns text, type echoes the resulting
// value, and scroll reports the resulting offset.
type BrowserOutput struct {
	ResultMeta

	// URL and Title describe the page after the action settled.
	URL   string `json:"url,omitempty"`
	Title string `json:"title,omitempty"`

	// Elements is the snapshot result.
	Elements []BrowserElement `json:"elements,omitempty"`

	// Text is the visible text returned by the text action.
	Text string `json:"text,omitempty"`

	// Value is the referenced control's value after a type action.
	Value string `json:"value,omitempty"`

	// ScrollX and ScrollY are the document scroll offsets after a scroll.
	ScrollX *int `json:"scroll_x,omitempty"`
	ScrollY *int `json:"scroll_y,omitempty"`

	// WindowID is the browser window the call acted on, which is useful when
	// the tool resolved it rather than the caller naming it.
	WindowID int `json:"window_id,omitempty"`

	// ClickMethod reports how a click was delivered: "pointer" for a real
	// pointer event at the element's screen position, or "script" for a
	// JavaScript el.click().
	//
	// The distinction is not cosmetic. A scripted click is not a user
	// gesture, so anything gated on user activation -- the Fullscreen API,
	// clipboard access, autoplay -- refuses it, and refuses it SILENTLY: the
	// call reports success and nothing happens. Surfacing which path ran lets
	// a caller understand a click that "worked" but did nothing.
	ClickMethod string `json:"click_method,omitempty"`

	// Truncated reports that a snapshot hit MaxElements and omitted elements.
	Truncated bool `json:"truncated,omitempty"`
}

// BrowserToolDescription is shared by RegisterAll and the gateway so the
// advertised description cannot drift between the stub server and the real one.
const BrowserToolDescription = "Drive web content by ref from the page's own accessibility " +
	"information: navigate, snapshot, click, type, press, scroll, back, text."

