func TestClassifyReadsTheLabelsFromBeforeTheRename(t *testing.T) {
	labels := map[string]string{"io.kairos.hadron-desktop.flavor": "sway", "io.kairos.hadron-desktop.version": "v9.9.9", "io.kairos.hadron-desktop.gpu": "vm"}
	v, err := Classify(policyInfo(t, "example.com/other/img:latest", labels), policyRel(), nil)
	want := Verdict{Flavor: "sway", Version: "v9.9.9", GPU: "vm", Isotope: true}
	if err != nil || v != want {
		t.Fatalf("got %+v, %v; want %+v", v, err, want)
	}
}

func TestClassifyRefusesAnOldAgentImage(t *testing.T) {
	labels := map[string]string{"io.kairos.hadron-desktop.flavor": "agent", "io.kairos.hadron-desktop.version": "v9.9.9"}
	if _, err := Classify(policyInfo(t, "example.com/other/img:latest", labels), policyRel(), nil); !errors.Is(err, ErrAgentImage) {
		t.Fatalf("err = %v, want ErrAgentImage", err)
	}
}

// The new label wins when an image carries both.
func TestClassifyPrefersTheNewLabel(t *testing.T) {
	labels := map[string]string{labelFlavor: "i3", "io.kairos.hadron-desktop.flavor": "sway", labelVersion: "v9.9.9"}
	v, err := Classify(policyInfo(t, "example.com/other/img:latest", labels), policyRel(), nil)
	if err != nil || v.Flavor != "i3" {
		t.Fatalf("got %+v, %v; want flavor i3", v, err)
	}
}

package main

import (
	"gioui.org/layout"
	"gioui.org/widget"

	"github.com/kairos-community/isotope/guikit"
)

func init() { pageMakers[PageSecurity] = func(u *UI) pageView { return &securityPage{u: u} } }

// securityPage: whether the disk is encrypted, and on an encrypted disk its
// keys (RecoveryStatus, polkit's recovery action). Replacing the recovery
// key stays `isotope recovery new-key` until phase 2.
type securityPage struct {
	u    *UI
	list widget.List

	// Under u.mu.
	rec     RecoveryStatus
	loaded  bool
	loadErr string
}

func (p *securityPage) Shown() {
	u, d := p.u, p.u.hooks.Daemon
	if d == nil || !u.sys.Encrypted || !u.sys.Admin {
		return
	}
	u.async(func() {
		st, err := d.RecoveryStatus()
		u.mu.Lock()
		defer u.mu.Unlock()
		if err != nil {
			p.loadErr = "Could not read the disk's keys: " + Describe(err)
			return
		}
		p.rec, p.loaded, p.loadErr = st, true, ""
	})
}

func (p *securityPage) Update(layout.Context) {}

func (p *securityPage) Footer() (leading, trailing []guikit.Action) { return nil, nil }

func (p *securityPage) Body(gtx layout.Context) layout.Dimensions {
	u := p.u
	u.mu.Lock()
	rec, loaded, loadErr := p.rec, p.loaded, p.loadErr
	u.mu.Unlock()
	return u.scrolled(gtx, &p.list, func(gtx layout.Context) layout.Dimensions {
		var c col
		c.add(u.Heading("Security", "Disk encryption keeps your files unreadable without the passphrase, the recovery key or this computer's TPM."))
		c.gap(24)
		if !u.sys.Encrypted {
			c.add(u.lead("The disk is not encrypted"))
			c.gap(6)
			c.add(u.para("Encryption is chosen when Isotope is installed (\"Encrypt your files?\"). To encrypt this machine, back it up, install again with encryption on, and restore the backup."))
			return c.layout(gtx)
		}
		c.add(u.lead("The disk is encrypted"))
		c.gap(12)
		switch {
		case !u.sys.Admin:
			c.add(u.notice("Only an administrator (a member of the admin group) can see and change the disk's keys."))
		case loadErr != "":
			c.add(u.errorBox(loadErr))
		case !loaded:
			c.add(u.spinnerLine("Reading the disk's keys…"))
		default:
			c.add(u.panel(func(gtx layout.Context) layout.Dimensions {
				var rows col
				for i, l := range RecoveryLines(rec) {
					if i > 0 {
						rows.gap(6)
					}
					rows.add(u.dim(l))
				}
				return rows.layout(gtx)
			}))
		}
		c.gap(28)
		c.add(u.caps("RECOVERY KEY"))
		c.gap(10)
		c.add(u.para("A recovery key opens the disk when the passphrase is lost or the TPM refuses (after a firmware update). To create a new one, which replaces the old one, run this in a terminal:"))
		c.gap(10)
		c.add(u.panel(func(gtx layout.Context) layout.Dimensions {
			return u.Label(gtx, guikit.StMono13, guikit.ColText, "isotope recovery new-key")
		}))
		c.gap(8)
		c.add(u.dim("Creating it here is coming in a later version of this page."))
		return c.layout(gtx)
	})
}

package main

import (
	"errors"
	"regexp"
	"strings"
)

// Image labels the Dockerfile's kairos stage writes (Task 11 uses the same
// strings). They let an image outside the release repo, such as a mirror,
// declare that it is an Isotope image.
const (
	labelFlavor  = "io.kairos.isotope.flavor"
	labelVersion = "io.kairos.isotope.version"
	labelHadron  = "io.kairos.isotope.hadron-version"
	// labelGPU is the image line, full or vm. Images up to v0.0.7 have
	// none.
	labelGPU = "io.kairos.isotope.gpu"
	// labelTrustedBoot is "true" on a Trusted Boot (UKI) upgrade image,
	// <flavor>-uki-<tag> (release.yml, job build-uki).
	labelTrustedBoot = "io.kairos.isotope.trusted-boot"
)

var (
	// ErrAgentImage is never overridable: the agent flavor has no daemon, so
	// switching a desktop system onto it would remove its own updater.
	ErrAgentImage = errors.New("this is an agent image; the desktop updater cannot install it")
	// ErrServerImage and ErrDesktopImage keep the two editions apart, and
	// are never overridable either: a desktop installed over a server, or a
	// server over a desktop, is a different system, not an upgrade.
	ErrServerImage  = errors.New("this is a server edition image; a desktop system cannot install it")
	ErrDesktopImage = errors.New("this is a desktop image; the server edition installs only server images")
	// ErrNotIsotope and ErrNotRelease are the refusals the daemon's advanced
	// mode may override.
	ErrNotIsotope = errors.New("this is not an Isotope image")
	// ErrNotRelease is the daemon's refusal of an image that Classify
	// accepts but does not trust: labelled as Isotope, but not a published
	// release of the release repository. The spec accepts images from other
	// repositories only through advanced mode.
	ErrNotRelease = errors.New("this is not a published Isotope release")
	// ErrTrustedBootImage and ErrNeedsTrustedBoot keep the uki line apart
	// from the others, and are never overridable: kairos-agent on a Trusted
	// Boot system installs only a signed UKI, and a UKI container written
	// to a GRUB system's slot does not boot.
	ErrTrustedBootImage = errors.New("this is a Trusted Boot (UKI) image; only a system that boots with Trusted Boot can install it")
	ErrNeedsTrustedBoot = errors.New("this system boots with Trusted Boot; it installs only the signed Trusted Boot (UKI) images of Isotope releases")
)

// desktopFlavors are the flavors that ship the daemon and tray.
var desktopFlavors = map[string]bool{"sway": true, "i3": true, "cosmic": true, "niri": true}

// installable are the flavors a system of rel's flavor may install: a server
// only server images, anything else only the desktops.
func installable(rel Release) map[string]bool {
	if rel.Flavor == flavorServer {
		return map[string]bool{flavorServer: true}
	}
	return desktopFlavors
}

// editionRefusal is the error for an image of flavor on a system of rel's
// flavor when the two are not the same edition, or nil.
func editionRefusal(rel Release, flavor string) error {
	switch {
	case rel.Flavor == flavorServer && desktopFlavors[flavor]:
		return ErrDesktopImage
	case rel.Flavor != flavorServer && flavor == flavorServer:
		return ErrServerImage
	}
	return nil
}

// strictTag is vX.Y.Z only: no prerelease, no build metadata, no leading zeros.
var strictTag = regexp.MustCompile(`^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$`)

// Verdict says what an image is and how far it is trusted.
type Verdict struct {
	Flavor, Version string
	// GPU is the image line, gpuFull or gpuVM, or "" when a labelled image
	// does not say. An image on the other line than the running system is
	// installed like one of another flavor: allowed, and the CLI says so.
	GPU     string
	Trusted bool // named like a release published in the release repo
	Isotope bool // trusted, or labelled as a desktop image
}

// Classify decides whether info may be installed. The agent check runs first
// and wins over every other signal, so a label cannot launder an agent image.
// The edition check runs next, on the label and on a release repo tag, so a
// server image cannot pass for a desktop one or the other way round.
func Classify(info ImageInfo, rel Release, published []Latest) (Verdict, error) {
	if label(info, labelFlavor) == "agent" || strings.HasPrefix(info.Ref.Tag, "agent-") {
		return Verdict{}, ErrAgentImage
	}
	if err := editionRefusal(rel, label(info, labelFlavor)); err != nil {
		return Verdict{}, err
	}
	if tagFlavor, _, ok := strings.Cut(info.Ref.Tag, "-"); ok && rel.ImageRepo != "" && info.Ref.Repo() == rel.ImageRepo {
		if err := editionRefusal(rel, tagFlavor); err != nil {
			return Verdict{}, err
		}
	}
	allowed := installable(rel)

	// The uki line next: neither line may install the other's images.
	uki := ukiImage(info)
	if rel.TrustedBoot {
		return classifyTrustedBoot(info, rel, published, allowed, uki)
	}
	if uki {
		return Verdict{}, ErrTrustedBootImage
	}

	// Trusted by name: the repo and a tag that a published release maps to.
	// A digest-only ref has no tag, and a tag+digest ref is resolved by the
	// digest, so the tag says nothing about the content: neither is trusted by
	// name. Both can still be labelled.
	if rel.ImageRepo != "" && info.Ref.Digest == "" && info.Ref.Repo() == rel.ImageRepo {
		flavor, tag, ok := strings.Cut(info.Ref.Tag, "-")
		line := gpuFull
		if rest, isVM := strings.CutPrefix(tag, gpuVM+"-"); isVM {
			line, tag = gpuVM, rest
		}
		if ok && allowed[flavor] && (flavor != flavorServer || line == gpuFull) && strictTag.MatchString(tag) {
			if isPublished(tag, published) {
				return Verdict{Flavor: flavor, Version: tag, GPU: line, Trusted: true, Isotope: true}, nil
			}
		}
	}

	flavor, version := label(info, labelFlavor), label(info, labelVersion)
	if allowed[flavor] && strictTag.MatchString(version) {
		line := label(info, labelGPU)
		if line != gpuFull && line != gpuVM {
			line = ""
		}
		return Verdict{Flavor: flavor, Version: version, GPU: line, Isotope: true}, nil
	}
	return Verdict{}, ErrNotIsotope
}

// ukiImage reports whether info looks like a Trusted Boot image: a
// trusted-boot label that is not "false", or a tag with -uki- in it, from
// any repository. A GRUB system refuses all of them.
func ukiImage(info ImageInfo) bool {
	if v := label(info, labelTrustedBoot); v != "" && v != "false" {
		return true
	}
	return strings.Contains(info.Ref.Tag, "-"+lineUKI+"-")
}

// classifyTrustedBoot is Classify on a Trusted Boot system. Trusted by name
// is only <flavor>-uki-<tag> of a published release in the release repo;
// by label, the image must say trusted-boot=true. Everything else is
// ErrNeedsTrustedBoot, except an image that looks like a UKI but is not
// published or fully labelled, which is ErrNotIsotope (the daemon does not
// let advanced mode lift it on Trusted Boot).
func classifyTrustedBoot(info ImageInfo, rel Release, published []Latest, allowed map[string]bool, uki bool) (Verdict, error) {
	if rel.ImageRepo != "" && info.Ref.Digest == "" && info.Ref.Repo() == rel.ImageRepo {
		flavor, rest, ok := strings.Cut(info.Ref.Tag, "-")
		tag, isUKI := strings.CutPrefix(rest, lineUKI+"-")
		if ok && isUKI && allowed[flavor] && strictTag.MatchString(tag) && isPublished(tag, published) {
			return Verdict{Flavor: flavor, Version: tag, GPU: lineUKI, Trusted: true, Isotope: true}, nil
		}
	}
	flavor, version := label(info, labelFlavor), label(info, labelVersion)
	if label(info, labelTrustedBoot) == "true" && allowed[flavor] && strictTag.MatchString(version) {
		return Verdict{Flavor: flavor, Version: version, GPU: lineUKI, Isotope: true}, nil
	}
	if uki {
		return Verdict{}, ErrNotIsotope
	}
	return Verdict{}, ErrNeedsTrustedBoot
}

// legacyLabelPrefix is the label prefix from before the rename to Isotope.
// Images built before it carry only these labels, and an agent image among
// them must still be refused.
const (
	labelPrefix       = "io.kairos.isotope."
	legacyLabelPrefix = "io.kairos.hadron-desktop."
)

// label returns the image's label key, or the same label under the old
// prefix when the image has no label of the new name.
func label(info ImageInfo, key string) string {
	if v, ok := info.Labels[key]; ok {
		return v
	}
	return info.Labels[legacyLabelPrefix+strings.TrimPrefix(key, labelPrefix)]
}

func isPublished(tag string, published []Latest) bool {
	for _, p := range published {
		if p.Tag == tag {
			return true
		}
	}
	return false
}

// ReleaseRef is the reference release.yml pushes for flavor and tag on the
// running system's line. It returns an error, not a zero value, when the
// release has no image repo or the parts do not form a valid reference.
func ReleaseRef(rel Release, flavor, tag string) (ImageRef, error) {
	return LineRef(rel, flavor, rel.Line(), tag)
}

// LineRef is ReleaseRef for a given line, which `switch --gpu` changes.
func LineRef(rel Release, flavor, line, tag string) (ImageRef, error) {
	if rel.ImageRepo == "" {
		return ImageRef{}, errors.New("release has no image repository")
	}
	return ParseRef(rel.ImageRepo + ":" + lineTag(flavor, line, tag))
}

// lineLabels are the words the CLI and the tray use for the lines.
var lineLabels = map[string]string{
	gpuFull: "hardware (Intel and AMD GPU drivers, firmware)",
	gpuVM:   "virtual machine (no GPU drivers or firmware)",
	lineUKI: "Trusted Boot (signed UKI, hardware image)",
}

// advancedAllowed reports whether advanced mode may lift a refusal on rel:
// never on Trusted Boot, where only a signed UKI can be installed.
func advancedAllowed(rel Release) bool {
	return !rel.TrustedBoot && AdvancedEnabled()
}
